import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.Dsf4_p3t.js";const u=JSON.parse('{"title":"src/native/ — 平台原生调优层","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/native-layer.md","filePath":"zh/guide/native-layer.md","lastUpdated":1791258210000}'),r={name:"zh/guide/native-layer.md"};function i(c,t,n,l,s,p){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="src-native-—-平台原生调优层" tabindex="-1">src/native/ — 平台原生调优层 <a class="header-anchor" href="#src-native-—-平台原生调优层" aria-label="Permalink to &quot;src/native/ — 平台原生调优层&quot;">​</a></h1><p><strong>本目录是框架代码中唯一允许直接调用操作系统底层 API 的地方。</strong></p><h2 id="放什么" tabindex="-1">放什么 <a class="header-anchor" href="#放什么" aria-label="Permalink to &quot;放什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>文件</th></tr></thead><tbody><tr><td>接口声明</td><td><code>native_tuning.h</code>（<code>neoflux::native</code> 命名空间）</td></tr><tr><td>Windows 调优</td><td><code>windows/platform_win32.cpp</code>（线程优先级、<code>timeBeginPeriod(1)</code>、cpuid/xgetbv）</td></tr><tr><td>Linux/Android 调优</td><td><code>linux/platform_linux.cpp</code>（SCHED_FIFO→nice 降级、cpuid/getauxval）</td></tr><tr><td>macOS/iOS 调优</td><td><code>apple/platform_apple.cpp</code>（QoS class、sysctl）</td></tr><tr><td>其他平台兜底</td><td><code>platform_common.cpp</code>（全部 no-op）</td></tr></tbody></table><p>当前能力：渲染线程/UI 线程调度整形、帧节拍定时器精度、CPU SIMD 特性检测（SSE4.2 / AVX2 / ASIMD / FP16，含 OS 支持校验）。</p><h2 id="不放什么-历史教训" tabindex="-1">不放什么（历史教训） <a class="header-anchor" href="#不放什么-历史教训" aria-label="Permalink to &quot;不放什么（历史教训）&quot;">​</a></h2><ul><li><strong>任何渲染 / GPU API</strong>——GPU 后端代码全部位于 tgfx 之后，后端选择是 tgfx 自己的 <code>TGFX_USE_*</code> 编译期开关（见 <code>thirdparty/CMakeLists.txt</code>）。 曾经出现在这里的 <code>gl/gl_functions.{h,cpp}</code>（自管 GL 加载器）是 架构错位的死代码，已在 <code>refactor_strip-gl-from-core</code> 中删除。</li><li><strong>媒体解码 / 视频互操作</strong>——属于 GL 后端模块（<code>src/media/</code>）。</li><li><strong>窗口系统</strong>——属于 <code>src/renderers/glfw_bridge.cpp</code> 或 <code>mobile_bridge.cpp</code>。</li></ul><h2 id="约定" tabindex="-1">约定 <a class="header-anchor" href="#约定" aria-label="Permalink to &quot;约定&quot;">​</a></h2><ul><li>所有入口 <strong>best-effort</strong>：权限不足/平台不支持时静默降级并记一条日志， 绝不抛异常、绝不使调用方失败。</li><li>新增调优能力时：先在 <code>native_tuning.h</code> 定义跨平台语义， 再在四个实现里补齐，兜底实现必须同步更新。</li><li>CMake 侧按平台自动选择实现（<code>neoflux/CMakeLists.txt</code> 中 &quot;Platform-native tuning layer&quot; 块），无需手动指定。</li></ul>',9)])])}const _=e(r,[["render",i]]);export{u as __pageData,_ as default};
